const cb = $json.callback_query || {};
const data = cb.data || '';
const [action, requestId] = data.split(':');
return {
  action,
  request_id: requestId || '',
  manager_telegram_id: cb.from && cb.from.id ? String(cb.from.id) : '',
  callback_query_id: cb.id || '',
  manager_chat_id: cb.message && cb.message.chat ? String(cb.message.chat.id) : '',
  manager_message_id: cb.message ? cb.message.message_id : null
};

const bal = $json;
const req = $('Find Leave Request').item.json;
const field = 'used_' + req.leave_type;
const updated = { ...bal };
updated[field] = Number(bal[field] || 0) + Number(req.days || 0);
return updated;
